begin;
select plan(39);
select has_table('public','article_review_plans','private review-plan relation exists');
select is((select count(*)::int from public.article_review_plans),0,'migration creates no default plans');
select ok((select relrowsecurity from pg_class where oid='public.article_review_plans'::regclass),'plan RLS enabled');
select ok(not has_table_privilege('anon','public.article_review_plans','select'),'no anon plan read grant');
select ok(not has_table_privilege('service_role','public.article_review_plans','select'),'no service-key bypass grant');
select ok((select not prosecdef from pg_proc where oid='public.save_article_review_plan(uuid,text,integer,date,uuid,bigint)'::regprocedure),'save RPC is security invoker');
insert into auth.users(id,email) values
('00000000-0000-4000-8000-000000003301','review-plan-admin@example.test'),
('00000000-0000-4000-8000-000000003302','review-plan-seo@example.test'),
('00000000-0000-4000-8000-000000003303','review-plan-user@example.test');
update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000003301';
update public.profiles set role='seo_editor' where id='00000000-0000-4000-8000-000000003302';
insert into public.blog_posts(id,slug,title,published,content) values('00000000-0000-4000-8000-000000003311','review-plan-fixture','Unchanged synthetic article',true,'{"excerpt":"Original fixture"}');
create temporary table review_plan_baseline as select to_jsonb(p) as snapshot from public.blog_posts p where id='00000000-0000-4000-8000-000000003311';
create temporary table review_audit_baseline as select count(*) as rows,(select last_value from public.content_revisions_revision_number_seq) as sequence from public.content_revisions;
grant select on review_plan_baseline,review_audit_baseline to authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000003301',true);
set local role authenticated;
select is(public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',6,'2026-10-06',null,null)->>'interval_months','6','admin saves a private cadence');
create temporary table first_review_plan as select * from public.article_review_plans;
select is((select next_due_on::text from public.article_review_plans),'2026-10-06','calendar due date is preserved');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',6,'2026-10-06',null,null)$$,'P0001',null,'old unplanned form cannot overwrite');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','publish',6,'2026-10-06',null,null)$$,'22023',null,'plan cannot publish an article');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',0,'2026-10-06',(select id from first_review_plan),1)$$,'23514',null,'zero cadence rejects');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',37,'2026-10-06',(select id from first_review_plan),1)$$,'23514',null,'cadence above 36 rejects');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',6,'2026-02-30',(select id from first_review_plan),1)$$,'22008',null,'impossible calendar rejects');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',6,'infinity',(select id from first_review_plan),1)$$,'23514',null,'infinite date rejects');
select is((select version::int from public.article_review_plans),1,'failed submissions preserve generation');
select is(public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',36,'2024-02-29',(select id from first_review_plan),1)->>'version','2','valid leap date and maximum cadence save');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',6,'2026-10-06',(select id from first_review_plan),1)$$,'P0001',null,'stale generation rejects');
update public.article_review_plans set id='00000000-0000-4000-8000-000000003399',version=1,created_at='1900-01-01';
select is((select id from public.article_review_plans),(select id from first_review_plan),'raw admin update cannot replace identity');
select is((select version::int from public.article_review_plans),3,'raw update also advances generation');
select ok((select created_at>'1900-01-01'::timestamptz from public.article_review_plans),'raw update preserves creation time');
reset role;
set local role anon;
select throws_ok('select * from public.article_review_plans','42501',null,'anonymous plans are unreadable');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',6,'2026-10-06',null,null)$$,'42501',null,'anon cannot call RPC');
select is((select content->>'excerpt' from public.blog_posts where id='00000000-0000-4000-8000-000000003311'),'Original fixture','public article stays readable and unchanged');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000003302',true);
set local role authenticated;
select is((select count(*)::int from public.article_review_plans),0,'SEO editor cannot see plans');
with changed as(update public.article_review_plans set interval_months=1 returning id) select is((select count(*)::int from changed),0,'SEO editor cannot update plans');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','clear',null,null,null,null)$$,'42501',null,'SEO editor cannot call RPC');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000003303',true);
set local role authenticated;
select is((select count(*)::int from public.article_review_plans),0,'ordinary user cannot see plans');
with changed as(delete from public.article_review_plans returning id) select is((select count(*)::int from changed),0,'ordinary user cannot delete plans');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','clear',null,null,null,null)$$,'42501',null,'ordinary user cannot call RPC');
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role authenticated;
select is((select count(*)::int from public.article_review_plans),0,'no identity cannot see private plans');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','clear',null,null,null,null)$$,'42501',null,'no identity cannot call RPC');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000003301',true);
set local role authenticated;
select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','clear',null,null,(select id from public.article_review_plans),3);
select is((select count(*)::int from public.article_review_plans),0,'clear removes only plan');
select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',6,'2026-10-06',null,null);
select ok((select id from public.article_review_plans)<>(select id from first_review_plan),'recreated plan has fresh identity');
select is((select version::int from public.article_review_plans),1,'ABA fixture repeats numeric version');
select throws_ok($$select public.save_article_review_plan('00000000-0000-4000-8000-000000003311','save',6,'2026-10-06',(select id from first_review_plan),1)$$,'P0001',null,'opaque identity prevents ABA overwrite');
select is((select to_jsonb(p) from public.blog_posts p where id='00000000-0000-4000-8000-000000003311'),(select snapshot from review_plan_baseline),'all article fields including Updated remain identical');
select is((select count(*) from public.content_revisions),(select rows from review_audit_baseline),'planning writes never append article revisions');
reset role;
select is((select last_value from public.content_revisions_revision_number_seq),(select sequence from review_audit_baseline),'planning leaves audit sequence unchanged');
delete from public.blog_posts where id='00000000-0000-4000-8000-000000003311';
select is((select count(*)::int from public.article_review_plans),0,'article deletion cascades private plan');
select * from finish();
rollback;
